fn refit_medusa_side_lasers(&mut self, tick: u64) -> Result<(), SaveError> {
    use super::{ModuleAction, ModuleKind, ModuleSlot};

    let (dock, _, revision) = self.xyzzy_medusa_issue().ok_or(INVALID)?;
    let ledger = self
        .modular
        .ledger(self, self.commander_account.as_ref().ok_or(INVALID)?)?;
    let mut stored: Vec<_> = ledger
        .items
        .iter()
        .filter(|item| item.kind == ModuleKind::NavalLaser && item.slot.is_none())
        .map(|item| item.id)
        .collect();
    for facing in super::medusa_lasers::INTEGRAL {
        let occupant = ledger
            .items
            .iter()
            .find(|item| item.slot == Some(ModuleSlot::laser(facing)));
        if occupant.is_some_and(|item| item.kind == ModuleKind::NavalLaser) {
            continue;
        }
        let original =
            super::modular::issued_laser_id(dock, revision, facing).ok_or(INVALID)?;
        let index = stored
            .iter()
            .position(|id| *id == original)
            .or_else(|| stored.len().checked_sub(1))
            .ok_or(INVALID)?;
        let action = ModuleAction::InstallLaser {
            item: stored.remove(index),
            replacing: occupant.map(|item| item.id),
            facing,
        };
        let review = self.review_module(action, tick).map_err(|_| INVALID)?;
        self.prepare_module(review, tick)
            .map_err(|_| INVALID)?
            .commit();
    }
    Ok(())
}

fn medusa_reissue_refits_owned_naval_lasers_without_losing_paid_guns() {
    use crate::FlightView::{Front, Left, Rear, Right};

    let mut w = World::new_commander(31815).unwrap();
    apply(&mut w, XyzzyAction::ActivateMedusa);
    let mounts = [Front, Rear, Left, Right];
    let initial = mounts.map(|f| w.laser_mount_snapshot(f).unwrap());
    let pulse = module(
        &mut w,
        ModuleAction::PurchaseLaser {
            kind: ModuleKind::PulseLaser,
            facing: Left,
        },
    );
    let beam = module(
        &mut w,
        ModuleAction::PurchaseLaser {
            kind: ModuleKind::BeamLaser,
            facing: Rear,
        },
    );
    let inventory = w.modular_equipment_snapshot().unwrap().items;
    let cash = w.credits_tenths();
    let mut w = cold(&w);
    assert_eq!(w.laser_mount_snapshot(Left).unwrap().fitted_item_id, pulse);
    assert_eq!(w.laser_mount_snapshot(Rear).unwrap().fitted_item_id, beam);
    for action in [
        XyzzyAction::MaximumSupportedHardware,
        XyzzyAction::ActivateMedusa,
    ] {
        apply(&mut w, action);
        w = cold(&w);
        let items = w.modular_equipment_snapshot().unwrap().items;
        assert_eq!(items.len(), inventory.len());
        for previous in &inventory {
            let restored = items.iter().find(|item| item.id == previous.id).unwrap();
            assert_eq!(restored.provenance, previous.provenance);
            if [pulse, beam].contains(&restored.id) {
                assert!(restored.slot.is_none());
            }
        }
        assert_eq!(w.credits_tenths(), cash);
        assert_eq!(mounts.map(|f| w.laser_mount_snapshot(f).unwrap()), initial);
    }
}

